const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southernEthiopia = ee.Geometry.Polygon([
    [[34.0, 3.4], [42.0, 3.4], [42.0, 9.0], [34.0, 9.0], [34.0, 3.4]]
  ]);

  // Time periods
  const targetPeriod = ['2021-10-01', '2021-11-30'];
  const baselineStart = '2000-10-01';
  const baselineEnd = '2013-11-30';

  // 2. Data Acquisition - CHIRPS Precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Target period (2021 Oct-Nov)
  const targetCollection = chirps
    .filterDate(targetPeriod[0], targetPeriod[1])
    .filterBounds(southernEthiopia);

  // Baseline period (2000-2013 Oct-Nov)
  const baselineCollection = chirps
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.calendarRange(10, 11, 'month'))
    .filterBounds(southernEthiopia);

  // Check collection sizes
  const targetSize = targetCollection.size().getInfo();
  const baselineSize = baselineCollection.size().getInfo();

  console.log(`Target period (2021) images: ${targetSize}`);
  console.log(`Baseline period (2000-2013) images: ${baselineSize}`);

  if (targetSize === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean precipitation
  const targetMean = targetCollection.mean();
  const baselineMean = baselineCollection.mean();

  // Calculate regional means
  const targetStats = targetMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernEthiopia,
    scale: 5000,
    maxPixels: 1e9
  });

  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernEthiopia,
    scale: 5000,
    maxPixels: 1e9
  });

  const targetRainfall = targetStats.get('precipitation').getInfo();
  const baselineRainfall = baselineStats.get('precipitation').getInfo();

  console.log(`2021 Oct-Nov mean rainfall: ${targetRainfall ? targetRainfall.toFixed(2) : 'No data'} mm`);
  console.log(`2000-2013 Oct-Nov mean rainfall: ${baselineRainfall ? baselineRainfall.toFixed(2) : 'No data'} mm`);

  // 4. Validation & Final Answer
  if (targetRainfall === null || baselineRainfall === null) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(targetRainfall) || isNaN(baselineRainfall)) {
    console.log("<answer>C3</answer>");
  } else if (targetRainfall < baselineRainfall) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
